/* Basic reset */
*{box-sizing:border-box;margin:0;padding:0;}
body{font-family:Arial,Helvetica,sans-serif;background:#f5f5f5;color:#333;}
header{display:flex;justify-content:space-between;align-items:center;padding:1rem;background:#4b3621;color:#fff;}
header h1{margin:0;font-size:1.5rem;}
#cart-button{background:none;border:none;color:#fff;font-size:1.5rem;position:relative;cursor:pointer;}
#cart-count{background:#e63946;color:#fff;border-radius:50%;padding:0.2rem 0.5rem;position:absolute;top:-10px;right:-10px;font-size:0.8rem;}
main#catalog{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:1rem;padding:1rem;}
.card{background:#fff;border-radius:8px;box-shadow:0 2px 5px rgba(0,0,0,0.1);overflow:hidden;display:flex;flex-direction:column;}
.card img{width:100%;height:150px;object-fit:cover;}
.card-content{padding:1rem;flex-grow:1;display:flex;flex-direction:column;}
.card-content h3{margin-bottom:0.5rem;font-size:1.2rem;}
.card-content p{flex-grow:1;font-size:0.9rem;color:#555;}
.card-content .price{font-weight:bold;margin:0.5rem 0;}
.card-content button{margin-top:auto;background:#4b3621;color:#fff;border:none;padding:0.5rem;border-radius:4px;cursor:pointer;}
.card-content button:hover{background:#3a2b1e;}
#cart-modal{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);display:flex;justify-content:center;align-items:center;}
#cart-modal.hidden{display:none;}
.cart-content{background:#fff;border-radius:8px;width:90%;max-width:500px;padding:1rem;position:relative;}
#close-cart{position:absolute;top:0.5rem;right:0.5rem;background:none;border:none;font-size:1.5rem;cursor:pointer;}
#cart-items{list-style:none;margin-top:1rem;max-height:300px;overflow-y:auto;}
#cart-items li{display:flex;justify-content:space-between;align-items:center;padding:0.5rem 0;border-bottom:1px solid #eee;}
#cart-items li button{background:none;border:none;color:#e63946;font-size:1rem;cursor:pointer;}
#cart-total{font-weight:bold;margin-top:1rem;}
#clear-cart{background:#e63946;color:#fff;border:none;padding:0.5rem 1rem;border-radius:4px;cursor:pointer;}
#clear-cart:hover{background:#c12e3c;}

